content.script:

/**
 * Prints a right-angled triangle pattern of stars with n rows.
 * @param {number} n - The number of rows in the triangle.
 * Example: For n = 5, the output will be:
    *
    * *
    * * *
    * * * *
    * * * * *
 */
function printRightAngledTriangle(n) {
    for (let i = 1; i <= n; i++) {
        let row = "";
        for (let j = 1; j <= i; j++) {
            row += "* ";
        }
        console.log(row);
    }
}
printRightAngledTriangle(5);
